TraSculptorMatrixD3.code:
// TraSculptor-style history tree + road-state matrix.
//
// Expected data shape:
// {
//   [stateKey]: {
//     parent: string | null,
//     "optimization improvement (%)": number,
//     "cumulative cost ($M)": number,
//     modification: string,
//     "modification type": string,
//     [roadName]: {
//       capacity: number,
//       "traffic flow": number,
//       FFTT: number,
//       "travel time": number
//     }
//   }
// }
//
// Fixes/features in this version:
// 1) tree circles align exactly with matrix columns,
// 2) matrix cells are taller than wide,
// 3) both inner rectangles stay inside each outer cell,
// 4) blue/orange backgrounds stay inside each outer cell,
// 5) flow > capacity may make the purple rectangle wider than
//    the white capacity rectangle, but never outside the cell,
// 6) tree nodes are kept away from cost/modification annotations,
//    preventing circle/label overlap.

const META_FIELDS = new Set([
  "parent",
  "optimization improvement (%)",
  "cumulative cost ($M)",
  "modification",
  "modification type",
]);

const stateKeys = Object.keys(data);

if (stateKeys.length === 0) return;

const props = params ?? {};

// ============================================================
// PROPS / LAYOUT
// ============================================================

const rowHeight = props.rowHeight ?? 56;

const headerHeight =
  props.headerHeight ?? 38;

const treeHeight =
  props.treeHeight ?? 130;

const labelColWidth =
  props.labelColWidth ?? 120;

const requestedCellW =
  props.cellWidth ?? 34;

const requestedCellH =
  props.cellHeight ?? 46;

const treeTopPadding =
  props.treeTopPadding ?? 10;

const treeBottomReserved =
  props.treeBottomReserved ?? 40;

const costYOffset =
  props.costYOffset ?? 28;

const modTypeYOffset =
  props.modTypeYOffset ?? 10;


// ============================================================
// COLORS
// ============================================================

const improveColor =
  props.color?.improve ??
  props.colors?.improve ??
  "#4C72B0";

const regressColor =
  props.color?.regress ??
  props.colors?.regress ??
  "#DD8452";

const neutralColor =
  "#9ca3af";

const glyphColor =
  props.glyphColor ??
  "#6d5bd0";


// ============================================================
// LABEL / DISPLAY OPTIONS
// ============================================================

const currencySymbol =
  props.currencySymbol ??
  "$";

const costSuffix =
  props.costSuffix ??
  "M";

const showCost =
  props.showCost ??
  true;

const showModificationType =
  props.showModificationType ??
  true;


// ============================================================
// DETERMINE ROAD ROWS
// ============================================================

let roadNames =
  props.roadOrder;

if (
  !Array.isArray(roadNames) ||
  roadNames.length === 0
) {
  roadNames = [];

  const seen =
    new Set();

  stateKeys.forEach((k) => {
    Object.keys(
      data[k] ?? {}
    ).forEach((field) => {
      if (
        META_FIELDS.has(field)
      ) {
        return;
      }

      const value =
        data[k][field];

      if (
        value &&
        typeof value === "object" &&
        !Array.isArray(value) &&
        !seen.has(field)
      ) {
        seen.add(field);
        roadNames.push(field);
      }
    });
  });
}


// ============================================================
// BASELINE
// ============================================================

const baselineKey =
  props.baselineKey ??
  stateKeys.find(
    (k) =>
      data[k]?.parent == null
  ) ??
  stateKeys[0];


// ============================================================
// SVG SIZE
// ============================================================

const width =
  containerWidth || 760;

const plotWidth =
  Math.max(
    width -
      labelColWidth -
      24,
    200
  );

const colWidth =
  props.colWidth ??
  plotWidth /
    stateKeys.length;

const matrixTop =
  headerHeight +
  treeHeight;

const height =
  matrixTop +
  roadNames.length *
    rowHeight +
  24;

const svg = d3
  .select(container)
  .append("svg")
  .attr(
    "width",
    width
  )
  .attr(
    "height",
    height
  )
  .style(
    "font-family",
    "Inter, sans-serif"
  );


// ============================================================
// SHARED COLUMN POSITIONING
// ============================================================

// Left edge of state column.
const xOf = (k) =>
  labelColWidth +
  stateKeys.indexOf(k) *
    colWidth;

// Exact center of state column.
//
// Tree node,
// state header,
// cost annotation,
// modification annotation,
// and matrix cell
// all share this x coordinate.
const xCenterOf = (k) =>
  xOf(k) +
  colWidth / 2;


// ============================================================
// B1 — HISTORY TREE
// ============================================================

const byKey =
  Object.fromEntries(
    stateKeys.map((k) => [
      k,
      {
        key: k,
        children: [],
      },
    ])
  );

const roots = [];

stateKeys.forEach((k) => {
  const parent =
    data[k]?.parent;

  if (
    parent &&
    byKey[parent]
  ) {
    byKey[parent]
      .children
      .push(byKey[k]);
  } else {
    roots.push(
      byKey[k]
    );
  }
});


// ============================================================
// TREE LAYOUT
// ============================================================

function countLeaves(node) {
  node.leaves =
    node.children.length === 0
      ? 1
      : node.children.reduce(
          (sum, child) =>
            sum +
            countLeaves(child),
          0
        );

  return node.leaves;
}

const totalLeaves =
  roots.reduce(
    (sum, root) =>
      sum +
      countLeaves(root),
    0
  ) || 1;


// ------------------------------------------------------------
// IMPORTANT:
// Reserve bottom area of tree for:
//
// cost
// modification type
//
// This prevents tree nodes from colliding with annotations.
// ------------------------------------------------------------

const treeUsableTop =
  treeTopPadding;

const treeUsableBottom =
  Math.max(
    treeUsableTop + 20,
    treeHeight -
      treeBottomReserved
  );

const treeUsableHeight =
  treeUsableBottom -
  treeUsableTop;


function assignY(
  node,
  y0,
  y1
) {
  node.y =
    (y0 + y1) / 2;

  let cursor =
    y0;

  node.children.forEach(
    (child) => {
      const span =
        (y1 - y0) *
        (
          child.leaves /
          node.leaves
        );

      assignY(
        child,
        cursor,
        cursor + span
      );

      cursor +=
        span;
    }
  );
}


let rootCursor =
  treeUsableTop;

roots.forEach(
  (root) => {
    const span =
      (
        root.leaves /
        totalLeaves
      ) *
      treeUsableHeight;

    assignY(
      root,
      rootCursor,
      rootCursor +
        span
    );

    rootCursor +=
      span;
  }
);


const treeG =
  svg
    .append("g")
    .attr(
      "transform",
      `translate(0, ${headerHeight})`
    );


// ============================================================
// TREE EDGES
