// ============================================================
// B2 — ROAD-STATE MATRIX
// ============================================================

// Determine largest relative travel-time difference
// from baseline.
//
// Used to determine background darkness.
let maxAbsDeltaFrac = 0;

stateKeys.forEach((k) => {
  if (
    k === baselineKey
  ) {
    return;
  }

  roadNames.forEach(
    (road) => {
      const current =
        data[k]?.[
          road
        ]?.[
          "travel time"
        ];

      const baseline =
        data[
          baselineKey
        ]?.[
          road
        ]?.[
          "travel time"
        ];

      if (
        current == null ||
        baseline == null ||
        baseline === 0
      ) {
        return;
      }

      const frac =
        Math.abs(
          current -
          baseline
        ) /
        baseline;

      maxAbsDeltaFrac =
        Math.max(
          maxAbsDeltaFrac,
          frac
        );
    }
  );
});


const matrixG =
  svg
    .append("g")
    .attr(
      "transform",
      `translate(0, ${matrixTop})`
    );


// ============================================================
// MATRIX ROWS
// ============================================================

roadNames.forEach(
  (
    road,
    rowIndex
  ) => {

    const rowY =
      rowIndex *
      rowHeight;


    // --------------------------------------------------------
    // Road label
    // --------------------------------------------------------

    matrixG
      .append("text")
      .attr(
        "x",
        labelColWidth -
          12
      )
      .attr(
        "y",
        rowY +
          rowHeight / 2 +
          4
      )
      .attr(
        "text-anchor",
        "end"
      )
      .style(
        "font-size",
        "11px"
      )
      .style(
        "font-weight",
        600
      )
      .attr(
        "fill",
        "#374151"
      )
      .text(
        road
      );


    const baselineTime =
      data[
        baselineKey
      ]?.[
        road
      ]?.[
        "travel time"
      ];


    // ========================================================
    // EACH STATE = ONE MATRIX CELL
    // ========================================================

    stateKeys.forEach(
      (
        k,
        columnIndex
      ) => {

        const metrics =
          data[k]?.[
            road
          ];

        const centerX =
          xCenterOf(k);


        // ----------------------------------------------------
        // Outer cell geometry
        // ----------------------------------------------------

        const cellW =
          Math.min(
            requestedCellW,
            Math.max(
              colWidth -
                12,
              8
            )
          );

        const cellH =
          Math.min(
            requestedCellH,
            Math.max(
              rowHeight -
                8,
              8
            )
          );


        // Matrix cell is centered exactly underneath
        // its corresponding history-tree circle.
        const cellX =
          centerX -
          cellW / 2;

        const cellY =
          rowY +
          (
            rowHeight -
            cellH
          ) /
          2;


        // ----------------------------------------------------
        // Missing road/state
        // ----------------------------------------------------

        if (!metrics) {
          matrixG
            .append("rect")
            .attr(
              "x",
              cellX
            )
            .attr(
              "y",
              cellY
            )
            .attr(
              "width",
              cellW
            )
            .attr(
              "height",
              cellH
            )
            .attr(
              "fill",
              "none"
            )
            .attr(
              "stroke",
              "#e5e7eb"
            )
            .attr(
              "stroke-dasharray",
              "2,2"
            )
            .attr(
              "rx",
              2
            );

          return;
        }


        // ----------------------------------------------------
        // Road metrics
        // ----------------------------------------------------

        const capacity =
          metrics.capacity;

        const flow =
          metrics[
            "traffic flow"
          ];

        const fftt =
          metrics.FFTT;

        const time =
          metrics[
            "travel time"
          ];


        // ====================================================
        // BACKGROUND COLOR
        // ====================================================

        let bg =
          "#ffffff";

        if (
          baselineTime != null &&
          baselineTime !== 0 &&
          k !== baselineKey
        ) {
          const delta =
            time -
            baselineTime;

          const magnitude =
            maxAbsDeltaFrac >
            0
              ? Math.abs(
                  delta
                ) /
                baselineTime /
                maxAbsDeltaFrac
              : 0;

          const lightness =
            94 -
            Math.min(
              magnitude,
              1
            ) *
              24;

          bg =
            delta < 0
              ? `hsl(215, 60%, ${lightness}%)`
              : delta > 0
                ? `hsl(28, 75%, ${lightness}%)`
                : "#ffffff";
        }


        // ====================================================
        // OUTER MATRIX CELL
        //
        // Blue/orange exists ONLY inside this rectangle.
        // ====================================================

        matrixG
          .append("rect")
          .attr(
            "x",
            cellX
          )
          .attr(
            "y",
            cellY
          )
          .attr(
            "width",
            cellW
          )
          .attr(
            "height",
            cellH
          )
          .attr(
            "fill",
            bg
          )
          .attr(
            "stroke",
            "#e5e7eb"
          )
          .attr(
            "stroke-width",
            0.8
          )
          .attr(
            "rx",
            2
          );


        // ====================================================
        // SAFE INNER AREA
        // ====================================================

        const outerPadX =
          props.cellPaddingX ??
          4;

        const outerPadY =
          props.cellPaddingY ??
          4;


        const innerX =
          cellX +
          outerPadX;

        const innerY =
          cellY +
          outerPadY;

        const innerW =
          Math.max(
            cellW -
              outerPadX *
                2,
            1
          );

        const innerH =
          Math.max(
            cellH -
              outerPadY *
                2,
            1
          );


        // ====================================================
        // CLIPPING REGION
        //
        // Absolute safeguard against any inner glyph overflow.
        // ====================================================

        const safeRoadId =
          String(
            road
          ).replace(
            /[^a-zA-Z0-9_-]/g,
            "_"
          );

        const safeStateId =
          String(
            k
          ).replace(
            /[^a-zA-Z0-9_-]/g,
            "_"
          );

        const clipId =
          `trasculptor-cell-${rowIndex}-${columnIndex}-${safeRoadId}-${safeStateId}`;


        const defs =
          svg
            .select(
              "defs"
            )
            .empty()
            ? svg.append(
                "defs"
              )
            : svg.select(
                "defs"
              );


        defs
          .append(
            "clipPath"
          )
          .attr(
            "id",
            clipId
          )
          .append(
            "rect"
          )
          .attr(
            "x",
            innerX
          )
          .attr(
            "y",
            innerY
          )
          .attr(
            "width",
            innerW
          )
          .attr(
            "height",
            innerH
          );


        const glyphG =
          matrixG
            .append("g")
            .attr(
              "clip-path",
              `url(#${clipId})`
            );


        // ====================================================
        // INNER RECTANGLE #1
        //
        // Capacity reference box
        // ====================================================

        const capBoxW =
          innerW *
          0.62;

        const capBoxH =
          innerH *
          0.82;

        const capBoxX =
          innerX +
          (
            innerW -
            capBoxW
          ) /
          2;

        const capBoxY =
          innerY +
          (
            innerH -
            capBoxH
          ) /
          2;


        glyphG
          .append("rect")
          .attr(
            "x",
            capBoxX
          )
          .attr(
            "y",
            capBoxY
          )
          .attr(
            "width",
            capBoxW
          )
          .attr(
            "height",
            capBoxH
          )
          .attr(
            "fill",
            "#ffffff"
          )
          .attr(
            "stroke",
            "#cbd5e1"
          )
          .attr(
            "stroke-width",
            1
          );


        // ====================================================
        // INNER RECTANGLE #2
        //
        // Actual road state
        //
        // width  = traffic flow / capacity
        // height = FFTT / actual travel time
        // ====================================================

        const flowRatio =
          capacity &&
          Number.isFinite(
            flow
          )
            ? flow /
              capacity
            : 0;


        const timeRatio =
          fftt &&
          time &&
          Number.isFinite(
            fftt
          ) &&
          Number.isFinite(
            time
          )
            ? Math.max(
                0,
                Math.min(
                  fftt /
                    time,
                  1
                )
              )
            : 0;


        // ----------------------------------------------------
        // Width
        //
        // ratio = 1
        // purple width == white capacity width
        //
        // ratio > 1
        // purple becomes wider, indicating congestion
        //
        // never exceeds innerW
        // ----------------------------------------------------

        const actualW =
          Math.max(
            1,
            Math.min(
              capBoxW *
                Math.max(
                  flowRatio,
                  0
                ),
              innerW
            )
          );


        // ----------------------------------------------------
        // Height
        //
        // Closer travel time is to FFTT,
        // taller the rectangle.
        // ----------------------------------------------------

        const actualH =
          Math.max(
            1,
            Math.min(
              capBoxH *
                timeRatio,
              capBoxH
            )
          );


        // Center actual flow rectangle horizontally.
        const actualX =
          innerX +
          (
            innerW -
            actualW
          ) /
          2;


        // Bottom-align it with capacity reference.
        const actualY =
          capBoxY +
          capBoxH -
          actualH;


        glyphG
          .append("rect")
          .attr(
            "x",
            actualX
          )
          .attr(
            "y",
            actualY
          )
          .attr(
            "width",
            actualW
          )
          .attr(
            "height",
            actualH
          )
          .attr(
            "fill",
            glyphColor
          )
          .attr(
            "fill-opacity",
            0.88
          );


        // ====================================================
        // TOOLTIP
        // ====================================================

        const tooltip =
          `${road} — ${k}\n` +
          `capacity: ${capacity}\n` +
          `traffic flow: ${flow} ` +
          `(${
            capacity
              ? (
                  flowRatio *
                  100
                ).toFixed(
                  0
                )
              : "?"
          }% of capacity)\n` +
          `FFTT: ${fftt}\n` +
          `travel time: ${time}`;


        glyphG
          .append("title")
          .text(
            tooltip
          );
      }
    );
  }
);
